package fr.cercle.decoupe;import java.util.*;public class EngineTest{static int n=0;static void ok(boolean b){n++;if(!b)throw new AssertionError("check "+n);}public static void main(String[] a){for(int seed=1;seed<=100;seed++){Engine e=new Engine(0,seed);for(int turn=0;turn<500&&!e.over;turn++){if(e.upgrade){int pick=0;for(int i=0;i<3;i++)if(e.offers[i]==2&&e.hp<30)pick=i;e.choose(pick);}else e.act(e.intent==2&&e.energy>0?2:e.intent==0?1:0);}ok(e.won&&e.round==6&&e.hp>0);int s=e.score;ok(!e.act(0)&&e.score==s);}Engine e=new Engine(0,4);for(int i=0;i<3;i++){e.intent=2;e.energy=0;ok(!e.act(2));}e=new Engine(1,1);float area=Engine.area(e.polygon);for(int i=1;i<100;i++){float x=100+520*i/100f;ArrayList<float[]> p=Engine.clip(e.polygon,x,300,x,1000,true),q=Engine.clip(e.polygon,x,300,x,1000,false);ok(Math.abs(Engine.area(p)+Engine.area(q)-area)<2);}for(int k=0;k<3;k++){float frac=e.target/100f;e.cut(100+520*frac,350,100+520*frac,980);ok(e.stage==1);e.keep(110,500);ok(Math.abs(e.percent()-e.target)<.1);e.validate();}ok(e.over&&e.score==300);e=new Engine(2,1);for(int room=0;room<3;room++){for(int gate=2;gate>=0;gate--){move(e,e.gaps[gate],500+gate*155+35);for(int t=0;t<300&&!e.open(gate);t++)e.tick(.02f);move(e,e.gaps[gate],500+gate*155-35);}move(e,360,375);}ok(e.over&&e.round==3);e=new Engine(2,4);e.time=1.5f;e.x=200;e.y=860;e.tx=200;e.ty=780;e.moving=true;for(int i=0;i<30;i++)e.tick(.02f);ok(e.y>820);System.out.println(n+" engine checks PASS");}static void move(Engine e,float x,float y){for(int i=0;i<2000&&!e.over;i++){e.tx=x;e.ty=y;e.moving=true;e.tick(.02f);if(Math.hypot(e.x-x,e.y-y)<2||e.time==0)break;}}}